import java.util.*;
import java.io.*;

public class Main {
    static class Flow {
        static final int N = 50 * 99 + 2;
        static final int M = 2 * N * 15 + N + 7;
        static int[] par = new int[N];
        static int[] first = new int[N];
        static int[] nxt = new int[2 * M];
        static int[] ep = new int[2 * M];
        static long[] flo = new long[2 * M];
        static long[] cap = new long[2 * M];
        static long[] cost = new long[2 * M];
        static int m;
        static int[] q = new int[N];
        static int[] inq = new int[N];
        static boolean[] vis = new boolean[N];
        static long[] pot = new long[N];
        static long[] dist = new long[N];

        static final long INF = 0x3f3f3f3f3f3f3f3fL;

        static void init() {
            m = 0;
            Arrays.fill(first, -1);
            Arrays.fill(flo, 0);
        }

        static void add_edge(int a, int b, long c, long p) {
            nxt[m] = first[ep[m] = a];
            first[ep[m]] = m;
            cap[m] = c;
            cost[m] = p;
            m++;
            nxt[m] = first[ep[m] = b];
            first[ep[m]] = m;
            cap[m] = 0;
            cost[m] = -p;
            m++;
        }

        static void mcf_pot_init(int n) {
            Arrays.fill(pot, 0);
            for (int k = 1; k < n; k++) {
                for (int e = 0; e < m; e++) {
                    if (cap[e] > 0) {
                        int u = ep[e];
                        int v = ep[e ^ 1];
                        if (pot[v] > pot[u] + cost[e]) {
                            pot[v] = pot[u] + cost[e];
                        }
                    }
                }
            }
        }

        static long mcf_update(int s, int t, long[] price, int n) {
            Arrays.fill(vis, false);
            Arrays.fill(dist, INF);
            Arrays.fill(inq, -1);
            dist[s] = 0;
            int qs = 0;
            q[qs++] = s;
            inq[s] = 0;
            while (qs > 0) {
                int u = q[0];
                System.arraycopy(q, 1, q, 0, qs - 1);
                qs--;
                inq[u] = -1;
                for (int i = first[u]; i != -1; i = nxt[i]) {
                    int v = ep[i ^ 1];
                    if (flo[i] < cap[i] && dist[v] > dist[u] + pot[u] - pot[v] + cost[i]) {
                        dist[v] = dist[u] + pot[u] - pot[v] + cost[i];
                        par[v] = i;
                        if (inq[v] < 0) {
                            q[qs++] = v;
                            inq[v] = qs - 1;
                        }
                        // Bubble up
                        int j = inq[v];
                        while (j > 0) {
                            int parentIdx = (j - 1) / 2;
                            if (dist[q[j]] >= dist[q[parentIdx]]) break;
                            int tmp = q[j];
                            q[j] = q[parentIdx];
                            q[parentIdx] = tmp;
                            inq[q[j]] = j;
                            inq[q[parentIdx]] = parentIdx;
                            j = parentIdx;
                        }
                    }
                }
            }
            if (dist[t] >= INF) return 0;
            long df = Long.MAX_VALUE;
            for (int e = t; e != s; e = ep[par[e]]) {
                df = Math.min(df, cap[par[e]] - flo[par[e]]);
            }
            for (int e = t; e != s; e = ep[par[e]]) {
                int edgeIdx = par[e];
                flo[edgeIdx] += df;
                flo[edgeIdx ^ 1] -= df;
                price[0] += df * cost[edgeIdx];
            }
            for (int i = 0; i < n; i++) {
                if (dist[i] < INF) {
                    pot[i] = Math.min(INF, dist[i] + pot[i]);
                }
            }
            return df;
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        int m = Integer.parseInt(st.nextToken());
        int k = Integer.parseInt(st.nextToken());
        int c = Integer.parseInt(st.nextToken());
        int d = Integer.parseInt(st.nextToken());

        final int T = 99;
        final int source = 0;
        final int sink = n * T + 1;

        Flow.init();

        for (int i = 0; i < k; i++) {
            int a = Integer.parseInt(br.readLine());
            Flow.add_edge(source, a, 1, 0);
        }

        for (int t = 0; t < T; t++) {
            Flow.add_edge(1 + t * n, sink, Long.MAX_VALUE, 0);
            if (t > 0) {
                for (int i = 1; i <= n; i++) {
                    Flow.add_edge(i + (t - 1) * n, i + t * n, Long.MAX_VALUE, c);
                }
            }
        }

        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            for (int j = 0; j < 15; j++) {
                int costVal = (j + 1) * (j + 1) - j * j;
                for (int t = 1; t < T; t++) {
                    long cost = costVal * d + c;
                    Flow.add_edge(a + (t - 1) * n, b + t * n, 1, cost);
                    Flow.add_edge(b + (t - 1) * n, a + t * n, 1, cost);
                }
            }
        }

        Flow.mcf_pot_init(Flow.N);
        long price = 0;
        long flow = 0;
        while (true) {
            long df = Flow.mcf_update(source, sink, new long[]{price}, Flow.N);
            if (df == 0) break;
            flow += df;
        }
        if (flow != k) {
            System.out.println("0");
        } else {
            System.out.println(price);
        }
    }
}
